#!/bin/bash
# Uninstall script for Loupdeck
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Loupdeck..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Loupdeck if running..."
pkill -f "Loupdeck" 2>/dev/null || true

# Unload service com.loupedeck.loupedeck2.launch
echo "Unloading service com.loupedeck.loupedeck2.launch..."
launchctl unload -w /Library/LaunchAgents/com.loupedeck.loupedeck2.launch.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.loupedeck.loupedeck2.launch.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.loupedeck.loupedeck2.launch.plist 2>/dev/null || true

# Kill application with bundle ID com.loupedeck.Loupedeck2 if running
echo "Stopping application with bundle ID com.loupedeck.Loupedeck2 if running..."
killall -9 "com.loupedeck.Loupedeck2" 2>/dev/null || true

# Kill application with bundle ID com.loupedeck.loupedeckconfig if running
echo "Stopping application with bundle ID com.loupedeck.loupedeckconfig if running..."
killall -9 "com.loupedeck.loupedeckconfig" 2>/dev/null || true

# Remove $HOME/Library/Application Support/Adobe/CameraRaw/Settings/Loupedeck - Karo Holmberg
echo "Removing $HOME/Library/Application Support/Adobe/CameraRaw/Settings/Loupedeck - Karo Holmberg..."
if [ -d "$HOME/Library/Application Support/Adobe/CameraRaw/Settings/Loupedeck - Karo Holmberg" ]; then
    rm -rf "$HOME/Library/Application Support/Adobe/CameraRaw/Settings/Loupedeck - Karo Holmberg" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/Adobe/CameraRaw/Settings/Loupedeck - Karo Holmberg" ]; then
